40	/* Memory-mapped register access macros
41	 * These provide direct register access without external dependencies
42	 */
43	
44	#define getreg32(addr)       (*(volatile uint32_t *)(addr))
45	#define putreg32(val, addr)  (*(volatile uint32_t *)(addr) = (val))
46	
47	/* GC2083 I2C Configuration
48	 * GC2083 supports two I2C addresses:
49	 *   - 7-bit: 0x37
50	 *   - 8-bit: 0x6E (write) / 0x6F (read)
51	 * Try 8-bit address first as it's more common in register-level access
52	 */
53	
54	#define GC2083_I2C_ADDR_7BIT    0x37
55	#define GC2083_I2C_ADDR_8BIT    0x6E
56	#define GC2083_I2C_ADDR         GC2083_I2C_ADDR_7BIT
57	#define GC2083_I2C_BUS          2
58	
59	/* GC2083 Chip ID Registers */
60	
61	#define GC2083_CHIP_ID_H_REG    0x03F0
62	#define GC2083_CHIP_ID_L_REG    0x03F1
63	#define GC2083_CHIP_ID          0x2083
64	
65	/* SG2000 I2C2 Controller Base Address */
66	
67	#define SG2000_I2C2_BASE        0x04020000UL
68	
69	/* I2C Register Offsets (DesignWare I2C) */
70	
71	#define I2C_CON                 0x00
72	#define I2C_TAR                 0x04
73	#define I2C_DATA_CMD            0x10
74	#define I2C_SS_SCL_HCNT         0x14
75	#define I2C_SS_SCL_LCNT         0x18
76	#define I2C_FS_SCL_HCNT         0x1C
77	#define I2C_FS_SCL_LCNT         0x20
78	#define I2C_SDA_HOLD            0x7C
79	#define I2C_ENABLE              0x6C
80	#define I2C_STATUS              0x70
81	#define I2C_ENABLE_STATUS       0x9C
82	
83	/* I2C Status Register Bits */
84	
85	#define I2C_STATUS_ACTIVITY     (1 << 0)
86	#define I2C_STATUS_TFNF         (1 << 1)
87	#define I2C_STATUS_TFE          (1 << 2)
88	#define I2C_STATUS_RFNE         (1 << 3)
89	#define I2C_STATUS_RFF          (1 << 4)
90	
91	/* I2C Command Register Bits */
92	
93	#define I2C_CMD_WRITE           0x000
94	#define I2C_CMD_READ            0x100
95	#define I2C_CMD_STOP            0x200
96	
97	/* I2C Control Register Bits */
98	
99	#define I2C_CON_MASTER          (1 << 0)
100	#define I2C_CON_SPEED_STD       (1 << 1)
101	#define I2C_CON_SPEED_FAST      (1 << 2)
102	#define I2C_CON_RESTART_EN      (1 << 5)
103	#define I2C_CON_SLAVE_DISABLE   (1 << 6)
104	
105	/* Clock Registers */
106	
107	#define SG2000_CLK_BASE         0x03002000UL
108	#define REG_CLK_EN_3            0x00C
109	#define REG_DIV_CLK_I2C         0x104
110	#define REG_CLK_BYP_0           0x080
111	
112	/* GPIO Registers */
113	
114	#define SG2000_GPIO_BASE        0x03020000UL
115	#define GPIO_OEN                0x04
116	#define GPIO_OUTPUT             0x00
117	
118	/* Camera MCLK Register */
119	
120	#define REG_CAM_MCLK_CTRL       0x03002090
121	
122	/* Log Macros */
123	
124	#define GC2083_ERR(fmt, ...)    syslog(LOG_ERR, "[GC2083][ERR] " fmt "\n", ##__VA_ARGS__)
125	#define GC2083_WARN(fmt, ...)   syslog(LOG_WARNING, "[GC2083][WARN] " fmt "\n", ##__VA_ARGS__)
126	#define GC2083_INFO(fmt, ...)   syslog(LOG_INFO, "[GC2083][INFO] " fmt "\n", ##__VA_ARGS__)
127	#define GC2083_DEBUG(fmt, ...)  syslog(LOG_DEBUG, "[GC2083][DEBUG] " fmt "\n", ##__VA_ARGS__)
