133	/* GPIO Pin Definitions for Milk-V Duos Camera Interface
134	 * According to schematic:
135	 *   - XGPIOC17: Sensor RESET (active low)
136	 *   - XGPIOC13: Sensor MCLK output (24MHz)
137	 */
138	
139	#define GPIO_PORT_C             2
140	#define PIN_RESET               17
141	#define PIN_MCLK                13
