147	/****************************************************************************
148	 * Name: gc2083_gpio_set_output
149	 *
150	 * Description:
151	 *   Set a GPIO pin on PORT C as output with specified value
152	 *
153	 ****************************************************************************/
154	
155	static void gc2083_gpio_set_output(int pin, int value)
156	{
157	  uint32_t base = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
158	  uint32_t reg;
159	
160	  /* Set as output (clear OEN bit) */
161	
162	  reg = getreg32(base + GPIO_OEN);
163	  reg &= ~(1 << pin);
164	  putreg32(reg, base + GPIO_OEN);
165	
166	  /* Set output value */
167	
168	  reg = getreg32(base + GPIO_OUTPUT);
169	  if (value)
170	    {
171	      reg |= (1 << pin);
172	    }
173	  else
174	    {
175	      reg &= ~(1 << pin);
176	    }
177	
178	  putreg32(reg, base + GPIO_OUTPUT);
179	}
