194	/****************************************************************************
195	 * Name: gc2083_i2c_init
196	 *
197	 * Description:
198	 *   Initialize I2C2 controller for GC2083 communication
199	 *
200	 ****************************************************************************/
201	
202	static int gc2083_i2c_init(void)
203	{
204	  uint32_t reg;
205	  int      timeout;
206	
207	  GC2083_INFO("Initializing I2C2 controller...");
208	
209	  /* Step 1: Enable I2C clock */
210	
211	  GC2083_DEBUG("Enabling I2C clock...");
212	
213	  /* Select clock source (osc = 25MHz) */
214	
215	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_BYP_0);
216	  reg |= (1 << 31);
217	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_BYP_0);
218	
219	  /* Set divider (divide by 1) */
220	
221	  reg = getreg32(SG2000_CLK_BASE + REG_DIV_CLK_I2C);
222	  reg &= ~(0xF << 16);
223	  reg |= (1 << 16);
224	  putreg32(reg, SG2000_CLK_BASE + REG_DIV_CLK_I2C);
225	
226	  /* Enable CLK_I2C */
227	
228	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_EN_3);
229	  reg |= (1 << 7);
230	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_EN_3);
231	
232	  GC2083_DEBUG("I2C clock enabled");
233	
234	  /* Step 2: Disable I2C controller */
235	
236	  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
237	
238	  /* Wait for controller to be disabled */
239	
240	  timeout = 1000;
241	  while (timeout-- > 0)
242	    {
243	      reg = getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS);
244	      if ((reg & 1) == 0)
245	        {
246	          break;
247	        }
248	
249	      gc2083_delay_ms(1);
250	    }
251	
252	  if (timeout <= 0)
253	    {
254	      GC2083_ERR("Failed to disable I2C controller");
255	      return -ETIMEDOUT;
256	    }
257	
258	  /* Step 3: Configure I2C controller
259	   * Master mode + Standard speed (100kHz) + Restart enable + Slave disable
260	   */
261	
262	  reg = I2C_CON_MASTER | I2C_CON_SPEED_STD |
263	        I2C_CON_RESTART_EN | I2C_CON_SLAVE_DISABLE;
264	  putreg32(reg, SG2000_I2C2_BASE + I2C_CON);
265	
266	  /* Step 4: Configure SCL timing for 100kHz
267	   * I2C clock = 25MHz
268	   * Standard mode: tHIGH = 4.0us, tLOW = 4.7us
269	   * HCNT = 25MHz * 4.0us = 100
270	   * LCNT = 25MHz * 4.7us = 117.5 ≈ 118
271	   */
272	
273	  putreg32(100, SG2000_I2C2_BASE + I2C_SS_SCL_HCNT);
274	  putreg32(118, SG2000_I2C2_BASE + I2C_SS_SCL_LCNT);
275	
276	  /* Step 5: Configure SDA hold time */
277	
278	  putreg32(0x1E, SG2000_I2C2_BASE + I2C_SDA_HOLD);
279	
280	  /* Step 6: Enable I2C controller */
281	
282	  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
283	
284	  GC2083_INFO("I2C2 controller initialized successfully");
285	
286	  return OK;
287	}
