289	/****************************************************************************
290	 * Name: gc2083_i2c_wait_tx_empty
291	 *
292	 * Description:
293	 *   Wait for TX FIFO to be empty
294	 *
295	 ****************************************************************************/
296	
297	static int gc2083_i2c_wait_tx_empty(void)
298	{
299	  int timeout = 1000;
300	
301	  while (timeout-- > 0)
302	    {
303	      uint32_t status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
304	      if (status & I2C_STATUS_TFE)
305	        {
306	          return OK;
307	        }
308	
309	      gc2083_delay_ms(1);
310	    }
311	
312	  return -ETIMEDOUT;
313	}
