341	/****************************************************************************
342	 * Name: gc2083_i2c_read_reg
343	 *
344	 * Description:
345	 *   Read a 16-bit register from GC2083
346	 *
347	 ****************************************************************************/
348	
349	static int gc2083_i2c_read_reg(uint16_t reg_addr, uint8_t *value)
350	{
351	  int ret;
352	  uint32_t status;
353	  int timeout;
354	
355	  GC2083_DEBUG("I2C read reg 0x%04X...", reg_addr);
356	
357	  /* Check I2C status before transfer */
358	
359	  status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
360	  GC2083_DEBUG("I2C status before transfer: 0x%08X", status);
361	
362	  /* Check if I2C is active */
363	
364	  if (status & I2C_STATUS_ACTIVITY)
365	    {
366	      GC2083_DEBUG("I2C is active");
367	    }
368	
369	  /* Send register address high byte */
370	
371	  timeout = 100;
372	  while (timeout-- > 0)
373	    {
374	      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
375	      if (status & I2C_STATUS_TFNF)
376	        {
377	          break;
378	        }
379	    }
380	
381	  if (timeout <= 0)
382	    {
383	      GC2083_ERR("TX FIFO full when sending addr high");
384	      return -ETIMEDOUT;
385	    }
386	
387	  putreg32(I2C_CMD_WRITE | ((reg_addr >> 8) & 0xFF),
388	           SG2000_I2C2_BASE + I2C_DATA_CMD);
389	
390	  /* Send register address low byte */
391	
392	  timeout = 100;
393	  while (timeout-- > 0)
394	    {
395	      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
396	      if (status & I2C_STATUS_TFNF)
397	        {
398	          break;
399	        }
400	    }
401	
402	  if (timeout <= 0)
403	    {
404	      GC2083_ERR("TX FIFO full when sending addr low");
405	      return -ETIMEDOUT;
406	    }
407	
408	  putreg32(I2C_CMD_WRITE | (reg_addr & 0xFF),
409	           SG2000_I2C2_BASE + I2C_DATA_CMD);
410	
411	  /* Send read command with stop */
412	
413	  timeout = 100;
414	  while (timeout-- > 0)
415	    {
416	      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
417	      if (status & I2C_STATUS_TFNF)
418	        {
419	          break;
420	        }
421	    }
422	
423	  if (timeout <= 0)
424	    {
425	      GC2083_ERR("TX FIFO full when sending read cmd");
426	      return -ETIMEDOUT;
427	    }
428	
429	  putreg32(I2C_CMD_READ | I2C_CMD_STOP,
430	           SG2000_I2C2_BASE + I2C_DATA_CMD);
431	
432	  /* Wait for data with timeout */
433	
434	  ret = gc2083_i2c_wait_rx_data();
435	  if (ret < 0)
436	    {
437	      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
438	      GC2083_ERR("Timeout waiting for I2C data, status=0x%08X", status);
439	
440	      /* Check for NACK or other errors */
441	
442	      uint32_t tx_abrt = getreg32(SG2000_I2C2_BASE + 0x80);
443	      GC2083_ERR("TX_ABRT_SOURCE = 0x%08X", tx_abrt);
444	
445	      return ret;
446	    }
447	
448	  /* Read data */
449	
450	  *value = (uint8_t)(getreg32(SG2000_I2C2_BASE + I2C_DATA_CMD) & 0xFF);
451	  GC2083_DEBUG("I2C read value = 0x%02X", *value);
452	
453	  return OK;
454	}
