456	/****************************************************************************
457	 * Name: gc2083_mclk_enable
458	 *
459	 * Description:
460	 *   Enable MCLK output for GC2083 sensor
461	 *   According to schematic, XGPIOC13 outputs MCLK (24MHz)
462	 *   Pinmux should be configured in board initialization
463	 *
464	 ****************************************************************************/
465	
466	static int gc2083_mclk_enable(void)
467	{
468	  uint32_t reg;
469	
470	  GC2083_INFO("Enabling MCLK output (24MHz)...");
471	
472	  /* Step 1: Configure Pinmux for XGPIOC13 as CAM_MCLK0
473	   * Pinmux Register: 0x03001000 + offset for MIPI_TXP1
474	   * Function: CAM_MCLK0
475	   *
476	   * Note: This should ideally be done in board initialization
477	   * but we do it here for completeness
478	   */
479	
480	  /* Step 2: Configure MCLK clock source and divider
481	   * CAM_MCLK0 clock tree:
482	   *   Source: CAM0PLL or OSC
483	   *   Divider: to produce 24MHz
484	   *
485	   * For 24MHz from OSC (25MHz):
486	   *   We need fractional divider or use CAM0PLL
487	   *
488	   * Register: REG_CAM_MCLK_CTRL (0x03002090)
489	   *   - Select clock source
490	   *   - Set divider
491	   */
492	
493	  /* Enable CAM0 clock in clock gate register */
494	  reg = getreg32(SG2000_CLK_BASE + 0x008);  /* REG_CLK_EN_2 */
495	  reg |= (1 << 16);  /* Enable CAM0 clock */
496	  putreg32(reg, SG2000_CLK_BASE + 0x008);
497	
498	  /* Configure CAM_MCLK output
499	   * The MCLK register controls the output frequency
500	   * We need to set it to produce 24MHz
501	   */
502	
503	  /* Set MCLK divider to produce 24MHz from source
504	   * If source is 96MHz (CAM0PLL), divider = 4
505	   * If source is 25MHz (OSC), we need fractional divider
506	   */
507	
508	  /* Configure MCLK control register */
509	  putreg32(0x04, SG2000_CLK_BASE + 0x090);  /* Set MCLK divider */
510	
511	  GC2083_DEBUG("MCLK output enabled on XGPIOC13 (24MHz)");
512	
513	  return OK;
514	}
