516	/****************************************************************************
517	 * Name: gc2083_reset
518	 *
519	 * Description:
520	 *   Reset the GC2083 sensor
521	 *
522	 ****************************************************************************/
523	
524	static int gc2083_reset(void)
525	{
526	  GC2083_INFO("Resetting GC2083 sensor...");
527	
528	  /* Assert reset (active low) */
529	
530	  GC2083_DEBUG("Asserting reset (LOW)...");
531	  gc2083_gpio_set_output(PIN_RESET, 0);
532	  gc2083_delay_ms(10);
533	
534	  /* Deassert reset */
535	
536	  GC2083_DEBUG("Deasserting reset (HIGH)...");
537	  gc2083_gpio_set_output(PIN_RESET, 1);
538	  gc2083_delay_ms(20);
539	
540	  GC2083_INFO("GC2083 sensor reset completed");
541	
542	  return OK;
543	}
