549	/****************************************************************************
550	 * Name: gc2083_detect
551	 *
552	 * Description:
553	 *   Detect GC2083 sensor by reading chip ID via I2C
554	 *
555	 * Returned Value:
556	 *   OK if sensor detected successfully, negative errno otherwise
557	 *
558	 ****************************************************************************/
559	
560	int gc2083_detect(void)
561	{
562	  uint8_t id_h;
563	  uint8_t id_l;
564	  uint16_t chip_id;
565	  int ret;
566	
567	  GC2083_INFO("========================================");
568	  GC2083_INFO("GC2083 Sensor Detection Start");
569	  GC2083_INFO("========================================");
570	
571	  /* Step 1: Enable MCLK output (24MHz) on XGPIOC13 */
572	
573	  ret = gc2083_mclk_enable();
574	  if (ret < 0)
575	    {
576	      GC2083_ERR("MCLK enable failed: %d", ret);
577	      return ret;
578	    }
579	
580	  /* Step 2: Reset sensor via XGPIOC17 */
581	
582	  ret = gc2083_reset();
583	  if (ret < 0)
584	    {
585	      GC2083_ERR("Reset failed: %d", ret);
586	      return ret;
587	    }
588	
589	  /* Step 3: Initialize I2C2 controller */
590	
591	  ret = gc2083_i2c_init();
592	  if (ret < 0)
593	    {
594	      GC2083_ERR("I2C init failed: %d", ret);
595	      return ret;
596	    }
597	
598	  /* Step 4: Set I2C target address
599	   * IMPORTANT: IC_TAR can only be written when I2C controller is disabled
600	   * We need to disable -> set TAR -> re-enable
601	   */
602	
603	  /* Disable I2C controller first */
604	  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
605	  gc2083_delay_ms(1);
606	
607	  /* Set target address */
608	  putreg32(GC2083_I2C_ADDR, SG2000_I2C2_BASE + I2C_TAR);
609	  GC2083_DEBUG("I2C target address set to 0x%02X", GC2083_I2C_ADDR);
610	
611	  /* Re-enable I2C controller */
612	  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
613	  gc2083_delay_ms(1);
614	
615	  /* Step 5: Read chip ID high byte from register 0x03F0 */
616	
617	  GC2083_DEBUG("Reading chip ID high byte (0x%04X)...", GC2083_CHIP_ID_H_REG);
618	  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
619	  if (ret < 0)
620	    {
621	      GC2083_ERR("Failed to read chip ID high byte: %d", ret);
622	
623	      /* Try with 8-bit address (0x6E) as fallback */
624	      GC2083_INFO("Trying with 8-bit address 0x6E...");
625	
626	      /* Disable I2C controller */
627	      putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
628	      gc2083_delay_ms(1);
629	
630	      /* Set 8-bit address */
631	      putreg32(GC2083_I2C_ADDR_8BIT, SG2000_I2C2_BASE + I2C_TAR);
632	      GC2083_DEBUG("I2C target address set to 0x%02X (8-bit)", GC2083_I2C_ADDR_8BIT);
633	
634	      /* Re-enable I2C controller */
635	      putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
636	      gc2083_delay_ms(1);
637	
638	      /* Retry read */
639	      ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
640	      if (ret < 0)
641	        {
642	          GC2083_ERR("Failed with 8-bit address too: %d", ret);
643	          return ret;
644	        }
645	    }
646	
647	  GC2083_DEBUG("Chip ID High = 0x%02X", id_h);
648	
649	  /* Step 6: Read chip ID low byte from register 0x03F1 */
650	
651	  GC2083_DEBUG("Reading chip ID low byte (0x%04X)...", GC2083_CHIP_ID_L_REG);
652	  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_L_REG, &id_l);
653	  if (ret < 0)
654	    {
655	      GC2083_ERR("Failed to read chip ID low byte: %d", ret);
656	      return ret;
657	    }
658	
659	  GC2083_DEBUG("Chip ID Low = 0x%02X", id_l);
660	
661	  /* Step 7: Combine and verify chip ID */
662	
663	  chip_id = ((uint16_t)id_h << 8) | id_l;
664	
665	  GC2083_INFO("========================================");
666	  GC2083_INFO("Chip ID Read Result:");
667	  GC2083_INFO("  Read:     0x%04X", chip_id);
668	  GC2083_INFO("  Expected: 0x%04X", GC2083_CHIP_ID);
669	  GC2083_INFO("========================================");
670	
671	  if (chip_id == GC2083_CHIP_ID)
672	    {
